import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { message } from 'antd';
import { loginSalesStaff } from '../../../services/auth';
import styles from './Login.module.css';
import gryphonLogo from '../../../assets/gryphon-logo-navy.png';

const Login = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState({
    email: '',
    password: ''
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    
    try {
      const response = await loginSalesStaff(formData);
      
      if (response.jwt) {
        // 儲存 token 和用戶資訊
        localStorage.setItem('token', response.jwt);
        localStorage.setItem('user', JSON.stringify(response.user));
        
        // 根據用戶角色導向不同頁面
        if (response.user.role === 'manager') {
          navigate('/crm/admin/overview');
        } else {
          navigate('/crm/sales');
        }
        
        message.success('登入成功');
      }
    } catch (error) {
      message.error('登入失敗，請檢查帳號密碼');
      console.error('Login error:', error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className={styles.loginContainer}>
      <div className={styles.loginBox}>
        <img
          src={gryphonLogo}
          alt="閣睿國際置業"
          style={{ display: 'block', width: '72%', margin: '0 auto 8px' }}
        />
        <h2>閣睿國際置業 CRM</h2>
        <form onSubmit={handleSubmit}>
          <div className={styles.formGroup}>
            <label htmlFor="email">帳號 / Email</label>
            <input
              type="text"
              id="email"
              name="email"
              value={formData.email}
              onChange={handleChange}
              required
              autoComplete="username"
            />
          </div>
          <div className={styles.formGroup}>
            <label htmlFor="password">密碼</label>
            <input
              type="password"
              id="password"
              name="password"
              value={formData.password}
              onChange={handleChange}
              required
            />
          </div>
          <button 
            type="submit" 
            className={styles.submitButton}
            disabled={loading}
          >
            {loading ? '登入中...' : '登入'}
          </button>
        </form>
      </div>
    </div>
  );
};

export default Login; 